preConditionHook:
// THE DOUBLE BOTTOM PULLBACK -- a NAMED Brooks setup and one of his most
// reliable buys: a three-push bottom whose third push down did not have
// strong-enough sellers to make a new low. After a double bottom has formed
// within the last patternWindow bars, this bar's low holds ABOVE the pattern's
// level, coming no closer than holdTicks and no further than testZoneAtr ATRs.
// The short is the double top pullback.
//
// CARRIED AS A COMPOSITE on purpose. ANDing a double-bottom rule with a
// higher-low rule does NOT reproduce it: the pane would not know that the
// higher low has to sit just above THAT level. The relationship between the
// third push and the pattern's own price is the setup.
//
// THE PATTERN. There is no DoubleExtreme rule on disk, so the pattern is
// inlined here and in the two DoubleExtreme* rules beside it, all three
// spelling it the same way: the two most recent CONFIRMED swing lows are
// within matchTicks of each other, and the more recent of them confirmed no
// more than patternWindow bars ago. matchTicks and pivotLookback ARE PROMOTED
// -- the merged parameters name neither the price tolerance that makes two
// lows "the same" nor the window the pivots are sought in. THE PATTERN'S LEVEL
// IS THE LOWER of the two lows (the higher of the two highs for a double top):
// it is the price a breakout has to clear, which is what keeps this rule, the
// breakout rule and the dip rule all reading one level.
//
// THE ZONE. holdTicks is the near edge and testZoneAtr the far edge, so the
// low must sit in a band just above the level. holdTicks IS ALLOWED TO GO
// NEGATIVE: Brooks treats the third push ending AT the level (a triple bottom)
// or slightly BELOW it and reversing (a failed breakout) as the same setup, so
// the near edge moves rather than the zone widening. Zone in ATRs for
// portability, near edge in ticks because the sources state it in ticks.
// Ticks division-first, ctx.MinMove() / ctx.PriceScale() computed once into
// tickSz; both are per-symbol constants (VERIFIED).
//
// PIVOT SCAN inlined from SwingHigh.json per the B-list decision, occurrences
// 1 and 2 only (occurrence 3+ is unmeasured). MEASURED (EL_Swing_Probe.txt,
// @ES 60 min): the pivot bar is AT OR ABOVE the `strength` OLDER bars and
// STRICTLY ABOVE the `strength` NEWER bars -- bars-ago indexing, so the newer
// bars are the smaller k and take el_gt / el_lt, the older el_ge / el_le;
// confirmation lag exactly `strength`; candidate offsets
// strength..pivotLookback-1, the neighbourhood reaching `strength` bars past
// the window, so the deepest bar touched is pivotLookback - 1 + strength. The
// comparisons carry the 2.22e-12 relational tolerance. A flat run of equal
// lows is ONE pivot, not N, which is what makes a "double" bottom two separate
// pushes rather than one shelf. The -1 sentinel is guarded on both bar indices.
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget. Seeded with a full sum on the first calculated bar or when
// the length changes, and updated thereafter as TWO statements -- EL evaluates
// S[1] + in - out left to right, and folding it to S += in - out rounds
// differently. The local counter is atrLen, not atrLength, which is the input.
//
// Not MicroDoubleExtreme, which matches two bar extremes at a fixed small lag;
// this pattern is two CONFIRMED PIVOTS any distance apart. Not Ledge, which
// counts bars matching the current bar's extreme inside a window. Not
// HigherSwingLow, which compares two pivots and knows nothing about a level.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
pivS = (int)strength;
pivW = (int)pivotLookback;
nHi = 0;
nLo = 0;
hiPx1 = -1.0;
hiBar1 = -1.0;
hiPx2 = -1.0;
hiBar2 = -1.0;
loPx1 = -1.0;
loBar1 = -1.0;
loPx2 = -1.0;
loBar2 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHi < 2) {
        nHi = nHi + 1;
        if (nHi == 1) { hiPx1 = high[j]; hiBar1 = (double)j; }
        if (nHi == 2) { hiPx2 = high[j]; hiBar2 = (double)j; }
    }
    if (okLo && nLo < 2) {
        nLo = nLo + 1;
        if (nLo == 1) { loPx1 = low[j]; loBar1 = (double)j; }
        if (nLo == 2) { loPx2 = low[j]; loBar2 = (double)j; }
    }
}
haveDb = (loBar1 != -1.0) && (loBar2 != -1.0) && el_le(loBar1, patternWindow)
    && el_le(std::fabs(loPx1 - loPx2), matchTicks * tickSz);
haveDt = (hiBar1 != -1.0) && (hiBar2 != -1.0) && el_le(hiBar1, patternWindow)
    && el_le(std::fabs(hiPx1 - hiPx2), matchTicks * tickSz);
dbLevel = loPx1;
if (el_lt(loPx2, loPx1)) dbLevel = loPx2;
dtLevel = hiPx1;
if (el_gt(hiPx2, hiPx1)) dtLevel = hiPx2;
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
